example.programlisting:
_cleanup_(sd_json_variant_unrefp) sd_json_variant *v = NULL;
int r;

r = sd_json_buildo(
                &v,
                SD_JSON_BUILD_PAIR_STRING("name", "foo"),
                SD_JSON_BUILD_PAIR_UNSIGNED("size", 4711),
                SD_JSON_BUILD_PAIR_CONDITION(!!description, "description", SD_JSON_BUILD_STRING(description)),
                SD_JSON_BUILD_PAIR_ARRAY("tags",
                                         SD_JSON_BUILD_STRING("a"),
                                         SD_JSON_BUILD_STRING("b")));
if (r < 0)
        return r;

_cleanup_(sd_json_variant_unrefp) sd_json_variant *v = NULL;
int r;

r = sd_json_build(
                &v,
                SD_JSON_BUILD_ARRAY(
                                SD_JSON_BUILD_STRING("foo"),
                                SD_JSON_BUILD_UNSIGNED(4711),
                                SD_JSON_BUILD_OBJECT(SD_JSON_BUILD_PAIR_BOOLEAN("enabled", true)),
                                SD_JSON_BUILD_NULL));
if (r < 0)
        return r;
